// @spec: COR
import fs from 'node:fs';
const c = JSON.parse(fs.readFileSync('config/runtime.json', 'utf8'));
if (!Number.isFinite(c.maxWaitMs) || c.maxWaitMs < 0) { console.error('RECOVERABLE_TECHNICAL: config/runtime.json maxWaitMs must be finite and nonnegative'); process.exit(2); }

// @file: Existing delay integration consumer.
// @spec: COR
// @consumers: inputs/brief.md
import { finiteNonnegative } from './number.ts';
/** @purpose Existing finite nonnegative input validator. */
export const acceptsDelay = (value: number): boolean => finiteNonnegative(value);

// @file: Approved normal and invalid-input scenarios.
// @spec: COR
// @consumers: N/A
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { boundedDelay } from './delay.ts';

test('[COR-REQ-1] public behavior', () => {
  // contract: finite nonnegative bounds select the smaller delay, and zero is a valid bound.
  // #region START_PUBLIC_BEHAVIOR_ASSERT_SELECTION
  assert.strictEqual(boundedDelay(25, 200), 25);
  assert.strictEqual(boundedDelay(200, 25), 25);
  assert.strictEqual(boundedDelay(75, 75), 75);
  assert.strictEqual(boundedDelay(0, 200), 0);
  assert.strictEqual(boundedDelay(200, 0), 0);
  assert.strictEqual(boundedDelay(0, 0), 0);
  // #endregion END_PUBLIC_BEHAVIOR_ASSERT_SELECTION
});

test('[COR-REQ-2] invalid input', () => {
  // failure mode: every invalid runtime argument is rejected with RangeError, never coerced to a delay.
  // #region START_INVALID_INPUT_ASSERT_REJECTION
  assert.throws(() => boundedDelay(-1, 50), RangeError);
  assert.throws(() => boundedDelay(50, -1), RangeError);
  assert.throws(() => boundedDelay(Number.NaN, 50), RangeError);
  assert.throws(() => boundedDelay(50, Number.NaN), RangeError);
  assert.throws(() => boundedDelay(Number.POSITIVE_INFINITY, 50), RangeError);
  assert.throws(() => boundedDelay(50, Number.POSITIVE_INFINITY), RangeError);
  assert.throws(() => boundedDelay(Number.NEGATIVE_INFINITY, 50), RangeError);
  assert.throws(() => boundedDelay(50, Number.NEGATIVE_INFINITY), RangeError);
  assert.throws(() => boundedDelay('50' as unknown as number, 50), RangeError);
  assert.throws(() => boundedDelay(50, undefined as unknown as number), RangeError);
  // #endregion END_INVALID_INPUT_ASSERT_REJECTION
});

// @file: Deterministic non-blocking delay selection.
// @spec: COR
// @consumers: fixture consumer

/**
 * @purpose Select the smaller of a requested delay and its upper limit without waiting.
 * @invariant Pure and synchronous: no timers, sleep, I/O, or input mutation; invalid input never yields a delay.
 * @param value Requested delay in milliseconds.
 * @param limit Upper bound in milliseconds.
 * @throws {RangeError} When either argument is not a finite nonnegative number.
 * @returns The smaller delay in milliseconds, exactly zero when either bound is zero.
 */
export function boundedDelay(value: number, limit: number): number {
  if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) {
    throw new RangeError(`[boundedDelay] value must be a finite nonnegative number, received ${String(value)}`);
  }
  if (typeof limit !== 'number' || !Number.isFinite(limit) || limit < 0) {
    throw new RangeError(`[boundedDelay] limit must be a finite nonnegative number, received ${String(limit)}`);
  }
  return Math.min(value, limit);
}

// @file: Shared numeric input validation for delay consumers.
// @spec: COR
// @consumers: acceptsDelay

/**
 * @purpose Verify that a runtime value is a finite number greater than or equal to zero.
 * @invariant Pure boolean predicate: no I/O, no mutation, and no throw for any input.
 * @param value Candidate numeric delay in milliseconds.
 * @returns True only for finite numeric values >= 0; false for every other input.
 */
export function finiteNonnegative(value: number): boolean {
  return typeof value === 'number' && Number.isFinite(value) && value >= 0;
}
